# Note: for exact transformations, use Yoshida order 2 because higher orders won't increase accuracy
@inline drift(tm::SciBmadStandard, kc, p_over_q_ref, bunch, L) = drift(Yoshida(order=2), kc, p_over_q_ref, bunch, L) 

@inline pure_rf(tm::SciBmadStandard, kc, p_over_q_ref, bunch, rfparams, beamlineparams, L)                = pure_rf(Yoshida(), kc, p_over_q_ref, bunch, rfparams, beamlineparams, L)                        
@inline pure_bsolenoid(tm::SciBmadStandard, kc, p_over_q_ref, bunch, bm0, L)                              = pure_bsolenoid(Yoshida(order=2), kc, p_over_q_ref, bunch, bm0, L)                             
@inline bsolenoid(tm::SciBmadStandard, kc, p_over_q_ref, bunch, bmultipoleparams, L)                      = bsolenoid(Yoshida(), kc, p_over_q_ref, bunch, bmultipoleparams, L)                     
@inline pure_bdipole(tm::SciBmadStandard, kc, p_over_q_ref, bunch, bm1, L)                                = pure_bdipole(Yoshida(order=2), kc, p_over_q_ref, bunch, bm1, L)                               
@inline bdipole(tm::SciBmadStandard, kc, p_over_q_ref, bunch, bmultipoleparams, L)                        = bdipole(Yoshida(), kc, p_over_q_ref, bunch, bmultipoleparams, L)                       
@inline pure_bquadrupole(tm::SciBmadStandard, kc, p_over_q_ref, bunch, bm2, L)                            = pure_bquadrupole(Yoshida(), kc, p_over_q_ref, bunch, bm2, L)                           
@inline bquadrupole(tm::SciBmadStandard, kc, p_over_q_ref, bunch, bmultipoleparams, L)                    = bquadrupole(Yoshida(), kc, p_over_q_ref, bunch, bmultipoleparams, L)                   
@inline pure_bmultipole(tm::SciBmadStandard, kc, p_over_q_ref, bunch, bmk, L)                             = pure_bmultipole(Yoshida(), kc, p_over_q_ref, bunch, bmk, L)                            
@inline bmultipole(tm::SciBmadStandard, kc, p_over_q_ref, bunch, bmultipoleparams, L)                     = bmultipole(Yoshida(), kc, p_over_q_ref, bunch, bmultipoleparams, L)                    
@inline bmultipole_rf(tm::SciBmadStandard, kc, p_over_q_ref, bunch, bmultipoleparams, rfparams, beamlineparams, L) = bmultipole_rf(Yoshida(), kc, p_over_q_ref, bunch, bmultipoleparams, rfparams, beamlineparams, L)
@inline bend_no_field(tm::SciBmadStandard, kc, p_over_q_ref, bunch, bendparams, L)                        = bend_no_field(Yoshida(order=2), kc, p_over_q_ref, bunch, bendparams, L)                       
@inline bend_pure_bsolenoid(tm::SciBmadStandard, kc, p_over_q_ref, bunch, bendparams, bm0, L)             = bend_pure_bsolenoid(Yoshida(), kc, p_over_q_ref, bunch, bendparams, bm0, L)            
@inline bend_bsolenoid(tm::SciBmadStandard, kc, p_over_q_ref, bunch, bendparams, bmultipoleparams, L)     = bend_bsolenoid(Yoshida(), kc, p_over_q_ref, bunch, bendparams, bmultipoleparams, L)    
@inline bend_pure_bdipole(tm::SciBmadStandard, kc, p_over_q_ref, bunch, bendparams, bm1, L)               = bend_pure_bdipole(Yoshida(order=2), kc, p_over_q_ref, bunch, bendparams, bm1, L)              
@inline bend_bdipole(tm::SciBmadStandard, kc, p_over_q_ref, bunch, bendparams, bmultipoleparams, L)       = bend_bdipole(Yoshida(), kc, p_over_q_ref, bunch, bendparams, bmultipoleparams, L)      
@inline bend_pure_bquadrupole(tm::SciBmadStandard, kc, p_over_q_ref, bunch, bendparams, bm2, L)           = bend_pure_bquadrupole(Yoshida(), kc, p_over_q_ref, bunch, bendparams, bm2, L)          
@inline bend_bquadrupole(tm::SciBmadStandard, kc, p_over_q_ref, bunch, bendparams, bmultipoleparams, L)   = bend_bquadrupole(Yoshida(), kc, p_over_q_ref, bunch, bendparams, bmultipoleparams, L)  
@inline bend_pure_bmultipole(tm::SciBmadStandard, kc, p_over_q_ref, bunch, bendparams, bmk, L)            = bend_pure_bmultipole(Yoshida(), kc, p_over_q_ref, bunch, bendparams, bmk, L)           
@inline bend_bmultipole(tm::SciBmadStandard, kc, p_over_q_ref, bunch, bendparams, bmultipoleparams, L)    = bend_bmultipole(Yoshida(), kc, p_over_q_ref, bunch, bendparams, bmultipoleparams, L)         
@inline implicit(tm::SciBmadStandard, kc, p_over_q_ref, bunch, bendparams, bmultipoleparams, L)           = implicit(Yoshida(), kc, p_over_q_ref, bunch, bendparams, bmultipoleparams, L)